// Parse unknown input safely: narrow with guards instead of casting
type Ok<T> = { ok: true; value: T };
type Err = { ok: false; error: string };
type Result<T> = Ok<T> | Err;

interface User { id: string; name: string; age: number }

function isUser(x: unknown): x is User {
  return typeof x === "object" && x !== null
    && typeof (x as Record<string, unknown>).id === "string"
    && typeof (x as Record<string, unknown>).name === "string"
    && typeof (x as Record<string, unknown>).age === "number";
}

function parseUser(json: string): Result<User> {
  let data: unknown;                                   // JSON.parse returns any; treat it as unknown
  try { data = JSON.parse(json); } catch { return { ok: false, error: "invalid JSON" }; }
  return isUser(data) ? { ok: true, value: data } : { ok: false, error: "not a User" };
}

const r = parseUser('{"id":"1","name":"Asha","age":30}');
if (r.ok) console.log(r.value.name);                   // narrowed: value exists only when ok is true
else console.error(r.error);

// Exhaustive switch helper
function assertNever(x: never): never { throw new Error(`Unhandled: ${JSON.stringify(x)}`); }

// The same validation at runtime in plain JS: types are erased, so runtime checks must exist anyway
// (in a TS project prefer a schema library such as zod and derive the type from the schema)
function parseUser(json) {
  let data;
  try { data = JSON.parse(json); } catch { return { ok: false, error: "invalid JSON" }; }
  const okShape = data && typeof data.id === "string" && typeof data.name === "string" && typeof data.age === "number";
  return okShape ? { ok: true, value: data } : { ok: false, error: "not a User" };
}

