// A typed event emitter and a typed fetch wrapper using generics, keyof and mapped types
type Events = { login: { userId: string }; logout: undefined; error: Error };

class Emitter<E extends Record<string, unknown>> {
  private handlers: { [K in keyof E]?: Array<(payload: E[K]) => void> } = {};
  on<K extends keyof E>(event: K, fn: (payload: E[K]) => void): () => void {
    (this.handlers[event] ??= []).push(fn);
    return () => { this.handlers[event] = this.handlers[event]?.filter((h) => h !== fn); };   // unsubscribe
  }
  emit<K extends keyof E>(event: K, payload: E[K]) { this.handlers[event]?.forEach((h) => h(payload)); }
}
const bus = new Emitter<Events>();
bus.on("login", (p) => console.log(p.userId));      // p is { userId: string }
bus.emit("login", { userId: "u1" });
// bus.emit("login", 5);                              // compile error

// Typed API client: one source of truth for routes
interface Api {
  "GET /users/:id": { params: { id: string }; response: { id: string; name: string } };
  "POST /users": { body: { name: string }; response: { id: string } };
}
async function call<K extends keyof Api>(route: K, args: Omit<Api[K], "response">): Promise<Api[K]["response"]> {
  const res = await fetch(String(route), { method: route.split(" ")[0], body: "body" in args ? JSON.stringify(args.body) : undefined });
  return res.json() as Promise<Api[K]["response"]>;    // cast at the boundary; validate with a schema in real code
}

# Python's typing offers generics too (static checkers like mypy/pyright read them; not enforced at runtime)
from typing import TypeVar, Generic, Callable, Iterable

T = TypeVar("T")
R = TypeVar("R")

def first(items: list[T]) -> T | None:
    return items[0] if items else None

class Stack(Generic[T]):
    def __init__(self) -> None: self._items: list[T] = []
    def push(self, x: T) -> None: self._items.append(x)
    def pop(self) -> T | None: return self._items.pop() if self._items else None

def map_values(d: dict[str, T], f: Callable[[T], R]) -> dict[str, R]:
    return {k: f(v) for k, v in d.items()}

// Result type + smart constructor + branded id
type Result<T, E = Error> = { ok: true; value: T } | { ok: false; error: E };
const ok = <T>(value: T): Result<T, never> => ({ ok: true, value });
const err = <E>(error: E): Result<never, E> => ({ ok: false, error });

type Email = string & { readonly __brand: "Email" };
function parseEmail(s: string): Result<Email, "invalid_email"> {
  return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s) ? ok(s as Email) : err("invalid_email");
}

function sendWelcome(to: Email) { /* only validated emails can reach here */ }

const r = parseEmail(input);
if (r.ok) sendWelcome(r.value);
else showError(r.error);          // r.error is exactly "invalid_email"

// Narrowing caught errors safely
try { await doWork(); }
catch (e: unknown) {
  if (e instanceof Error) log.error(e.message, { cause: e.cause });
  else log.error("non-error thrown", { e });
}

// JSDoc + checkJs gives gradual typing in plain JS without a build step
// @ts-check
/**
 * @template T
 * @param {T[]} items
 * @param {(item: T) => boolean} pred
 * @returns {T | undefined}
 */
export function find(items, pred) {
  for (const it of items) if (pred(it)) return it;
  return undefined;
}
